contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint addAmount, uint withdrawFirst) public payable {
        require(address(this).balance >= addAmount);
        uint balStart = address(this).balance;

        if (withdrawFirst == 0) {
            c.addToBalance{value: addAmount}();
        }

        uint userBalBefore = c.getBalance(address(this));
        bool withdrawReverted;
        try c.withdrawBalance() {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        if (withdrawFirst != 0) {
            c.addToBalance{value: addAmount}();
        }

        uint balEnd = address(this).balance;

        // General balance accounting: the test contract's net Ether change equals
        // (Ether received from withdrawBalance) - addAmount.
        // If withdrawBalance reverted, no Ether was received from it.
        assert(balEnd + addAmount == balStart + (withdrawReverted ? 0 : userBalBefore));
    }

    receive() external payable {}
}

